function authDialog() {
  const area = modal(`<p class="eyebrow">WELCOME TO STRGO</p><h2>继续你的创作。</h2><p class="muted">使用主站、生图、终端和社区共用的账号登录。</p><form id="login-form"><label>用户名<input name="username" autocomplete="username" required pattern="[A-Za-z0-9_-]{3,32}" placeholder="你的账号"></label><label>密码<input name="password" type="password" minlength="12" maxlength="128" autocomplete="current-password" required placeholder="至少 12 位"></label><label id="invite-label" hidden>邀请码<input name="invite" autocomplete="off"></label><p id="auth-error" class="error" role="alert"></p><button class="primary full" type="submit">登录创作空间 ${icon('arrow')}</button></form><button id="auth-switch" class="text-button">有邀请码？创建账号</button>`);
  let register = false;
  area.querySelector('#auth-switch').onclick = () => { register = !register; $('#invite-label').hidden = !register; $('#invite-label input').required = register; area.querySelector('button[type=submit]').textContent = register ? '创建账号' : '登录创作空间'; $('#auth-switch').textContent = register ? '已有账号，返回登录' : '有邀请码？创建账号'; area.querySelector('[name=password]').autocomplete = register ? 'new-password' : 'current-password'; };
  $('#login-form').onsubmit = async e => { e.preventDefault(); const button = e.target.querySelector('button'); button.disabled = true; try { await client.login(Object.fromEntries(new FormData(e.target)), register); location.assign(route === 'login' ? safeReturnPath(new URLSearchParams(location.search).get('next'), '/ai/') : location.href); } catch (error) { $('#auth-error').textContent = error.message; } finally { button.disabled = false; } };
}

async function musicPage() {
  $('#main').innerHTML = `<div class="page-heading"><div><h1>音乐工作台</h1><p>把想法写成旋律，让灵感被听见。</p></div><button class="secondary assistant-toggle">✳ 创作助手</button></div><div class="music-grid"><section class="panel music-composer"><div class="panel-title"><h2>新建音乐</h2><span id="save-state" class="saved-label">☁ 草稿自动保存</span></div><form id="music-form"><div class="segmented"><button type="button" data-mode="vocal" aria-pressed="true">✎　自定义歌词</button><button type="button" data-mode="instrumental" aria-pressed="false">⌁　纯音乐</button></div><label>作品标题<div class="counted"><input name="title" maxlength="100" placeholder="为这段旋律起个名字"><span id="title-count">0/100</span></div></label><label>风格描述<textarea name="prompt" maxlength="2000" rows="3" placeholder="温暖的中文流行，钢琴与弦乐，舒缓节奏，适合作为故事片尾曲。"></textarea><span class="field-count" id="prompt-count">0/2000</span></label><label>风格标签<input name="tags" maxlength="240" placeholder="中文流行, 温暖, 钢琴（用逗号分隔）"></label><div class="lyrics-label"><label for="lyrics">歌词</label><button id="write-lyrics" class="text-button" type="button">✧ 用助手改写</button></div><label class="sr-only" for="lyrics">歌词</label><textarea id="lyrics" name="lyrics" maxlength="3500" rows="11" placeholder="[Verse]\n雨停在站台边\n风吹过你的肩\n\n[Chorus]\n把我们的故事，写进下一段旋律…"></textarea><div id="lyrics-count" class="field-count">0/3500</div><fieldset><legend>作品时长</legend><div class="duration-options">${[15, 30, 60, 120].map(v => `<button type="button" data-duration="${v}" aria-pressed="${v === 60}">${v} 秒</button>`).join('')}</div></fieldset><label class="model-row"><span>使用模型</span><select name="model_id" aria-label="音乐生成模型">${state.models.filter(m => m.kind === 'music').map(m => `<option value="${esc(m.id)}" data-strgo-ui-copy ${m.available === false ? 'disabled' : ''}>${esc(modelLabel(m))}${m.available === false ? ' · 不可用' : ''}</option>`).join('') || '<option value="" data-strgo-ui-copy>暂无已授权的音乐模型</option>'}</select></label><label class="checkbox small"><input type="checkbox" name="local_only">仅使用本地音乐模型</label><details class="advanced"><summary>☷　高级参数 <span>⌄</span></summary><div class="advanced-grid"><label>BPM<input name="bpm" type="number" min="30" max="300" placeholder="模型默认"></label><label>调性<select name="key"><option value="">模型默认</option>${['C major', 'G major', 'D major', 'A minor', 'E minor'].map(v => `<option>${v}</option>`).join('')}</select></label><label>随机种子<input name="seed" type="number" min="0" max="2147483647" placeholder="随机"></label></div><p class="muted small">参数支持情况取决于模型；在线纯音乐不接受随机种子。</p></details><p class="error" id="music-error" role="alert"></p><button type="submit" id="generate-music" class="primary full generate">✦ 确认生成</button><div class="composer-note"><span id="generation-note">✧ 本次占用 60 秒额度</span><span>${icon('lock')} 私有作品</span></div></form></section><section class="panel music-results"><div class="panel-title"><h2>我的音乐</h2><div class="view-switch"><button id="refresh-music" class="icon-button" aria-label="刷新音乐">↻</button><a class="icon-button" href="/ai/assets/" aria-label="打开作品库">${icon('assets')}</a></div></div><div id="music-results"></div></section><div class="assistant-column"><strgo-assistant></strgo-assistant></div></div>`;
  const params = new URLSearchParams(location.search);
  if (state.session?.user) {
    const id = params.get('form');
    state.form = id ? await client.request('/forms/' + id) : await client.request('/forms', { method: 'POST', body: { kind: 'music', fields: { title: '', prompt: '', lyrics: '', duration: 60, instrumental: false, tags: [] } } });
    if (state.form.kind !== 'music') throw new Error('该草稿不属于音乐模块。');
    params.set('form', state.form.id); history.replaceState(null, '', location.pathname + '?' + params);
    fillMusicForm(state.form); await loadMusic();
  } else $('#music-results').innerHTML = empty('下一首作品，从一句话开始。', '登录后生成音乐，每一次灵感都会私密保存。');
  const component = $('strgo-assistant');
  await component.configure({ client, scope: 'music', formId: state.form?.id, revision: state.form?.revision, conversationId: params.get('conversation') || undefined, beforeSend: saveMusicForm });
  component.addEventListener('strgo:conversation-created', e => { const p = new URLSearchParams(location.search); p.set('conversation', e.detail.id); history.replaceState(null, '', location.pathname + '?' + p); });
  component.addEventListener('strgo:draft-applied', e => { state.form = e.detail; state.formDirty = false; fillMusicForm(e.detail); toastFixed('建议已应用，确认生成后才会创建音乐任务。'); });
  component.addEventListener('strgo:collapse', () => document.body.classList.toggle('assistant-collapsed'));
  action('.assistant-toggle', () => { document.body.classList.toggle('assistant-collapsed'); document.body.classList.toggle('assistant-mobile-open'); });
  action('#write-lyrics', () => { document.body.classList.remove('assistant-collapsed'); document.body.classList.add('assistant-mobile-open'); const input = component.shadowRoot.querySelector('textarea'); const example = '请根据当前音乐草稿优化歌词，保留意象，让副歌更温暖。'; input.value = window.strgoI18n?.translate(example) ?? example; input.focus(); });
  const form = $('#music-form');
  let saveTimer;
  form.oninput = () => { state.formDirty = true; counts(); clearTimeout(saveTimer); saveTimer = setTimeout(() => saveMusicForm().catch(e => { $('#save-state').textContent = '保存失败'; toast(e.message); }), 900); };
  form.onchange = () => updateAdvanced();
  document.querySelectorAll('[data-duration]').forEach(b => { b.onclick = () => { document.querySelectorAll('[data-duration]').forEach(v => v.setAttribute('aria-pressed', String(v === b))); state.formDirty = true; counts(); }; });
  document.querySelectorAll('[data-mode]').forEach(b => { b.onclick = () => { document.querySelectorAll('[data-mode]').forEach(v => v.setAttribute('aria-pressed', String(v === b))); $('#lyrics').disabled = b.dataset.mode === 'instrumental'; state.formDirty = true; updateAdvanced(); }; });
  form.onsubmit = e => { e.preventDefault(); generateMusic().catch(error => { $('#music-error').textContent = error.message; handleError(error); }); };
  action('#refresh-music', loadMusic); updateAdvanced();
  if (state.session?.user) state.polling = setInterval(() => loadMusic().catch(() => {}), 4000);
}
function counts() { const form = $('#music-form'); if (!form) return; for (const name of ['title', 'prompt', 'lyrics']) $('#' + name + '-count').textContent = `${form.elements[name].value.length}/${{ title: 100, prompt: 2000, lyrics: 3500 }[name]}`; $('#generation-note').textContent = `✧ 本次占用 ${document.querySelector('[data-duration][aria-pressed=true]').dataset.duration} 秒额度`; }
function fillMusicForm(form) {
  const fields = form.fields, element = $('#music-form');
  for (const name of ['title', 'prompt', 'lyrics', 'bpm', 'key', 'seed']) element.elements[name].value = fields[name] ?? '';
  element.elements.tags.value = (fields.tags || []).join(', ');
  document.querySelectorAll('[data-duration]').forEach(b => b.setAttribute('aria-pressed', String(Number(b.dataset.duration) === fields.duration)));
  document.querySelectorAll('[data-mode]').forEach(b => b.setAttribute('aria-pressed', String((b.dataset.mode === 'instrumental') === fields.instrumental)));
  $('#lyrics').disabled = fields.instrumental; $('#save-state').textContent = '☁ 草稿已保存'; counts();
}
function updateAdvanced() { const form = $('#music-form'), model = state.models.find(m => m.id === form.elements.model_id.value), instrumental = document.querySelector('[data-mode=instrumental]').getAttribute('aria-pressed') === 'true'; for (const name of ['bpm', 'key', 'seed']) form.elements[name].disabled = model?.adapter === 'eleven' && (name !== 'seed' || instrumental); }
function readMusicForm() {
  const form = $('#music-form'), fields = Object.fromEntries(['title', 'prompt', 'lyrics'].map(k => [k, form.elements[k].value]));
  fields.tags = form.elements.tags.value.split(/[,，]/).map(v => v.trim()).filter(Boolean); fields.instrumental = document.querySelector('[data-mode=instrumental]').getAttribute('aria-pressed') === 'true'; fields.duration = Number(document.querySelector('[data-duration][aria-pressed=true]').dataset.duration);
  for (const name of ['bpm', 'seed']) if (!form.elements[name].disabled && form.elements[name].value !== '') fields[name] = Number(form.elements[name].value);
  if (!form.elements.key.disabled && form.elements.key.value) fields.key = form.elements.key.value;
  return fields;
}
async function saveMusicForm() {
  if (!state.session?.user) { authDialog(); throw new Error('请先登录后保存草稿。'); }
  const work = async () => { if (!state.formDirty) return state.form; const fields = readMusicForm(); $('#save-state').textContent = '正在保存…';
    const result = await client.request('/forms/' + state.form.id, { method: 'PUT', body: { revision: state.form.revision, fields } }); state.form = result;
    state.formDirty = JSON.stringify(readMusicForm()) !== JSON.stringify(fields); $('#save-state').textContent = state.formDirty ? '有未保存修改' : '☁ 草稿已保存'; $('strgo-assistant')?.updateForm(result); return result; };
  state.saving = state.saving.catch(() => {}).then(work); return state.saving;
}
async function generateMusic() {
  if (!state.session?.user) return authDialog();
  $('#music-error').textContent = '';
  const button = $('#generate-music'); button.disabled = true;
  try {
    if (state.pendingMusic) { await submitMusic(); return; }
    const form = await saveMusicForm(), model = $('#music-form').elements.model_id.value;
    if (!model) throw new Error('暂无可用的音乐模型，请申请权限或联系管理员配置。');
    const body = { model_id: model, form_id: form.id, revision: form.revision, local_only: $('#music-form').elements.local_only.checked }, quote = await client.quote('music', body);
    const area = modal(`<p class="eyebrow">READY TO CREATE</p><h2 data-strgo-ui-copy>让这段灵感，被听见。</h2><div class="quote-summary"><span data-strgo-ui-copy>作品名称</span><strong ${form.fields.title ? 'data-strgo-user-content' : 'data-strgo-ui-copy'}>${esc(form.fields.title || '未命名音乐')}</strong><span data-strgo-ui-copy>生成时长</span><strong data-strgo-ui-copy>${quote.units} 秒</strong><span data-strgo-ui-copy>本次使用</span><strong data-strgo-ui-copy>${esc(costLabel(quote))}</strong></div><p class="muted"><span data-strgo-ui-copy>${quote.locality === 'cloud' ? '确认后，歌词与风格描述将发送至所选在线 API。' : '任务将在已登记的私有节点上执行。'}</span> <span data-strgo-ui-copy>作品默认仅自己可见。</span></p><p class="small muted" data-strgo-ui-copy>确认信息有效期 5 分钟。修改表单或模型后需重新确认。</p><button id="confirm-music" class="primary full" data-strgo-ui-copy>✦ 确认并生成</button>`);
    area.querySelector('#confirm-music').onclick = async event => { event.target.disabled = true; state.pendingMusic = { body: { ...body, quote_id: quote.id }, key: uuid7() }; try { await submitMusic(); $('#dialog').close(); } catch (error) { $('#music-error').textContent = error.message; toast(error.message); $('#dialog').close(); } };
  } finally { button.disabled = false; }
}
async function submitMusic() {
  try { await client.submit('music', state.pendingMusic.body, state.pendingMusic.key); state.pendingMusic = null; $('#generate-music').textContent = '✦ 确认生成'; toastFixed('已加入音乐任务队列。'); await loadMusic(); }
  catch (error) { if (error.status && error.status < 500) state.pendingMusic = null; else { $('#generate-music').textContent = '核对上次提交'; const hint = '点击“核对上次提交”会沿用原请求标识。'; error.message += ' ' + (window.strgoI18n?.translate(hint) ?? hint); } throw error; }
}
function audioCard(asset, featured = false) {
  return `<article class="music-card ${featured ? 'featured' : 'compact'}" data-asset="${asset.id}">${featured ? '<div class="cover"><img src="/ai/static/music-cover.svg" alt="STRGO 音乐流动金属封面" data-strgo-ui-copy></div>' : '<img class="mini-cover" src="/ai/static/music-cover.svg" alt="">'}<div class="track-info"><div class="track-heading"><h3>${esc(asset.title)}</h3><span class="status success" data-strgo-ui-copy><i class="dot"></i>已完成</span><button class="icon-button delete-asset" data-strgo-ui-copy data-id="${asset.id}" aria-label="删除 ${esc(asset.title)}">⋯</button></div><p class="track-meta">${Math.floor(asset.duration / 60).toString().padStart(2, '0')}:${Math.round(asset.duration % 60).toString().padStart(2, '0')}　·　<span data-strgo-ui-copy>私有音频</span>　·　${(asset.bytes / 1048576).toFixed(1)} MB</p><audio controls preload="none" src="${esc(asset.url)}" aria-label="播放 ${esc(asset.title)}" data-strgo-ui-copy></audio><div class="track-actions"><a class="secondary" href="${esc(asset.url)}?download=1" data-strgo-ui-copy>${icon('download')} 下载</a><button class="secondary reuse-track" data-task="${asset.task_id}" data-strgo-ui-copy>▢ 复用参数</button></div></div></article>`;
}
function bindAssetActions() {
  document.querySelectorAll('.delete-asset').forEach(b => { b.onclick = () => { modal(`<h2 data-strgo-ui-copy>删除这首作品？</h2><p class="muted" data-strgo-ui-copy>将移除作品并清理私有音频。任务记录保留供额度核对。</p><button id="delete-confirm" class="danger" data-strgo-ui-copy>确认删除</button>`); action('#delete-confirm', async () => { await client.request('/assets/' + b.dataset.id, { method: 'DELETE', body: {} }); $('#dialog').close(); toastFixed('作品已删除，音频清理已排队。'); state.resultFingerprint = null; if (route === 'music') await loadMusic(); else await assetsPage(); }); }; });
  document.querySelectorAll('.reuse-track').forEach(b => { b.onclick = async () => { try { const task = await client.request('/tasks/' + b.dataset.task); if (!task.parameters) throw new Error('该作品参数已超过保存期限。'); const copy = await client.request('/forms', { method: 'POST', body: { kind: 'music', fields: task.parameters } }); location.assign('/ai/music/?form=' + copy.id); } catch (e) { handleError(e); } }; });
}
