function modelEditor(model, nodes) {
  const c = model.config, cloud = model.locality === 'cloud';
  $('#model-editor').innerHTML = `<div class="panel-title"><h2>配置模型连接</h2><span class="status">${cloud ? '在线 API' : '本地模型'}</span></div><form id="model-form"><div class="form-columns"><label>连接名称<input name="name" value="${esc(model.name)}" maxlength="80" required></label><label>模型标识<input name="model" value="${esc(c.model)}" required></label></div><label>服务地址<input name="endpoint" value="${esc(c.endpoint)}" type="url" required placeholder="${cloud ? 'https://api.example.com' : 'http://10.0.0.2:11434'}"></label>${!cloud ? `<label>私有服务节点<select name="node_id"><option value="">请选择已登记节点</option>${nodes.map(n => `<option value="${n.id}" data-strgo-user-content ${c.node_id === n.id ? 'selected' : ''}>${esc(n.name)} · ${esc(n.resource_group)}</option>`).join('')}</select></label>` : ''}<label>API Key ${model.has_key ? '<span class="saved-key">已安全保存 · 留空保留</span>' : ''}<input name="api_key" type="password" autocomplete="new-password" placeholder="${model.has_key ? '••••••••••••••••••••••••' : '输入密钥，仅提交时可写入'}"></label>${model.has_key ? '<label class="checkbox"><input name="clear_key" type="checkbox">清除已保存的密钥</label>' : ''}${cloud ? `<div class="form-columns"><label>计价币种<select name="currency"><option ${c.currency === 'CNY' ? 'selected' : ''}>CNY</option><option ${c.currency === 'USD' ? 'selected' : ''}>USD</option></select></label><label>价格版本<input name="price_version" value="${esc(c.price_version || '')}" placeholder="例：2026-10 合同价"></label></div>${model.kind === 'chat' ? `<div class="form-columns"><label>输入价格上限 / 百万 tokens<input name="input_price" type="number" min="0" step="1" value="${c.input_price ?? ''}" placeholder="整数，按币种向上取整"></label><label>输出价格上限 / 百万 tokens<input name="output_price" type="number" min="0" step="1" value="${c.output_price ?? ''}"></label></div>` : `<label>每秒价格上限（所选币种）<input name="second_price" type="number" min="0" step="0.000001" value="${c.second_price == null ? '' : c.second_price / 1e6}"></label>`}` : ''}<label class="checkbox"><input type="checkbox" name="enabled" ${model.enabled ? 'checked' : ''}>启用供已授权成员使用</label><p class="form-help">${cloud ? '在线 API 需设置价格、预算并检查连接。密钥不能从浏览器读回。' : '服务地址须已登记于部署环境的内网白名单；本地 Ollama 不接受云端模型。'}</p><p id="model-error" class="error"></p><div class="button-row"><button class="primary" type="submit">保存配置</button><button id="check-model" type="button" class="secondary">检查连接 · 免费</button><a href="${model.kind === 'music' ? '/ai/music/' : '/ai/chat/'}" class="text-button">前往试用 ↗</a></div></form><p class="small muted">配置变更后须先保存、检查连接，再启用。试用沿用正常额度与费用确认流程。</p>`;
  $('#model-form').onsubmit = async e => { e.preventDefault(); const f = e.target, config = { endpoint: f.elements.endpoint.value, model: f.elements.model.value }; for (const k of ['api_key', 'price_version', 'currency', 'node_id']) if (f.elements[k]?.value) config[k] = f.elements[k].value;
    if (f.elements.clear_key) config.clear_key = f.elements.clear_key.checked;
    for (const k of ['input_price', 'output_price', 'second_price']) if (f.elements[k]?.value !== '' && f.elements[k]) config[k] = Math.ceil(Number(f.elements[k].value) * (k === 'second_price' ? 1e6 : 1));
    try { await client.request('/admin/models/' + model.id, { method: 'PUT', body: { name: f.elements.name.value, revision: model.revision, enabled: f.elements.enabled.checked && !Object.entries(config).some(([k,v]) => k === 'api_key' ? true : k === 'clear_key' ? v : c[k] !== v), config } }); toastFixed('配置已保存。'); await adminModels(); modelEditor(state.adminModels.find(m => m.id === model.id), nodes); }
    catch (error) { $('#model-error').textContent = error.message; handleError(error); }
  };
  action('#check-model', async () => { $('#check-model').disabled = true; try { await client.request('/admin/models/' + model.id + '/check', { method: 'POST', body: {} }); toastFixed('连接检查通过，未调用付费生成接口。'); await adminModels(); modelEditor(state.adminModels.find(m => m.id === model.id), nodes); } finally { if ($('#check-model')) $('#check-model').disabled = false; } });
}
async function adminMembers() {
  const members = await client.request('/admin/members');
  $('#admin-content').innerHTML = `<section class="panel table-panel"><div class="panel-title"><h2>成员与权限</h2><p class="muted small">管理身份与模块使用权分别控制。</p></div><div class="table-wrap"><table><thead><tr><th>成员</th><th>身份</th><th>模块权限</th><th>每日额度</th><th>状态</th><th>操作</th></tr></thead><tbody>${members.map(m => `<tr><td><strong>${esc(m.username)}</strong></td><td data-strgo-ui-copy>${m.role === 'admin' ? '管理员' : '成员'}</td><td data-strgo-ui-copy>${m.chat ? '对话' : '—'} / ${m.music ? '音乐' : '—'}</td><td data-strgo-ui-copy>${m.chat_limit} 次 / ${m.music_limit} 秒</td><td><span class="status ${m.status === 'active' ? 'success' : ''}" data-strgo-ui-copy>${m.status === 'active' ? '正常' : '已停用'}</span></td><td><button class="text-button member-edit" data-id="${m.id}">编辑授权 ↗</button></td></tr>`).join('')}</tbody></table></div></section><div id="member-drawer"></div>`;
  document.querySelectorAll('.member-edit').forEach(b => { b.onclick = () => memberDrawer(members.find(m => m.id === b.dataset.id)).catch(handleError); });
}
async function memberDrawer(member) {
  const models = await client.request('/admin/models');
  if (!$('#member-drawer')) $('#admin-content').insertAdjacentHTML('beforeend', '<div id="member-drawer"></div>');
  $('#member-drawer').innerHTML = `<div class="drawer-backdrop"></div><aside class="member-drawer" role="dialog" aria-modal="true" aria-label="编辑成员授权"><button id="close-drawer" class="dialog-x" aria-label="关闭授权编辑">×</button><p class="eyebrow">MEMBER ACCESS</p><h2>编辑成员授权</h2><div class="member-identity"><span class="account-avatar">${esc(member.username[0].toUpperCase())}</span><span><strong>${esc(member.username)}</strong><small>${member.role === 'admin' ? '管理员' : '创作成员'}</small></span></div><form id="member-form"><h3>模块使用权限</h3><label class="permission-check"><input name="chat" type="checkbox" ${member.chat ? 'checked' : ''}><span>AI 简单对话<small>独立对话与模块内创作助手</small></span></label><label class="permission-check"><input name="music" type="checkbox" ${member.music ? 'checked' : ''}><span>AI 音乐生成<small>按已授权模型生成音乐</small></span></label><h3>可使用模型</h3><div class="model-grants">${models.map(m => `<label class="checkbox"><input type="checkbox" name="models" value="${m.id}" ${member.models.includes(m.id) ? 'checked' : ''}><span><span data-strgo-user-content>${esc(m.name)}</span><small>${m.kind === 'chat' ? '对话' : '音乐'} · ${m.locality === 'local' ? '本地' : '在线 API'}</small></span></label>`).join('')}</div><h3>使用额度</h3><div class="form-columns"><label>对话 / 每天<input name="chat_limit" type="number" min="0" max="10000" value="${member.chat_limit}" required></label><label>音乐秒数 / 每天<input name="music_limit" type="number" min="0" max="86400" value="${member.music_limit}" required></label></div><label>授权有效期<select name="expiry"><option value="30">从今天起 30 天</option><option value="7">从今天起 7 天</option><option value="90">从今天起 90 天</option><option value="keep" selected>保留当前有效期</option><option value="forever">长期</option></select></label><label>账号状态<select name="status"><option value="active" ${member.status === 'active' ? 'selected' : ''}>正常</option><option value="disabled" ${member.status === 'disabled' ? 'selected' : ''}>停用并撤销登录</option></select></label><p class="small muted">管理身份不会自动获得模型权限或额度豁免。</p><p class="error" id="member-error"></p><button class="primary full">保存授权</button></form></aside>`;
  const close = () => $('#member-drawer').replaceChildren(); action('#close-drawer', close); $('.drawer-backdrop').onclick = close;
  $('#member-form').onsubmit = async e => { e.preventDefault(); const f = e.target, expiry = f.elements.expiry.value; try { await client.request('/admin/members/' + member.id, { method: 'PUT', body: { chat: f.elements.chat.checked, music: f.elements.music.checked, chat_limit: Number(f.elements.chat_limit.value), music_limit: Number(f.elements.music_limit.value), status: f.elements.status.value, expires: expiry === 'keep' ? member.expires : expiry === 'forever' ? null : Math.floor(Date.now() / 1000) + Number(expiry) * 86400, models: [...f.querySelectorAll('[name=models]:checked')].map(v => v.value) } }); toastFixed('成员授权已更新。'); await adminMembers(); } catch (error) { $('#member-error').textContent = error.message; handleError(error); } };
  $('#close-drawer').focus();
  const drawer = $('.member-drawer'); drawer.onkeydown = e => { if (e.key === 'Escape') close(); if (e.key === 'Tab') { const focusable = [...drawer.querySelectorAll('button,input,select')].filter(v => !v.disabled), index = focusable.indexOf(document.activeElement); if (e.shiftKey && index <= 0) { e.preventDefault(); focusable.at(-1).focus(); } else if (!e.shiftKey && index === focusable.length - 1) { e.preventDefault(); focusable[0].focus(); } } };
}
async function adminNodes() {
  const nodes = await client.request('/admin/nodes');
  $('#admin-content').innerHTML = `<div class="admin-lower"><section class="panel"><div class="panel-title"><h2>私有服务节点</h2></div>${nodes.map(n => `<div class="node-row"><div class="node-summary"><span class="node-device">▤</span><div><h3>${esc(n.name)}</h3><p>${esc(n.endpoint)}</p><small><span data-strgo-user-content>${esc(n.resource_group)}</span> · <span data-strgo-ui-copy>${n.lease ? 'GPU 任务占用中' : n.health === 'online' ? '已连接' : '待连接检查'} ${n.draining ? '· 排空中' : ''}</span></small></div></div><button class="secondary drain-node" data-id="${n.id}" data-draining="${n.draining}">${n.draining ? '恢复调度' : '排空节点'}</button></div>`).join('') || empty('登记第一台私有节点', '通过私有网络连接已有的模型服务。', 'admin')}<div class="info-note">同一 GPU 上的 Ollama 与 ACE-Step 即使端口不同，也应填写相同资源组。未知结果会保留资源锁，运维确认节点空闲后再恢复。</div></section><section class="panel"><h2>登记服务节点</h2><form id="node-form"><label>节点名称<input name="name" maxlength="80" placeholder="工作站 · Ollama" required></label><label>内网服务地址<input name="endpoint" type="url" placeholder="http://10.0.0.2:11434" required></label><label>GPU 资源组<input name="resource_group" pattern="[a-zA-Z0-9_-]+" placeholder="studio-gpu-01" maxlength="80" required></label><p class="muted small">地址必须已由运维加入服务器 AI_LOCAL_ENDPOINTS 白名单。请勿将模型端口直接暴露公网。</p><p id="node-error" class="error"></p><button class="primary full">保存节点</button></form></section></div>`;
  $('#node-form').onsubmit = async e => { e.preventDefault(); try { await client.request('/admin/nodes', { method: 'POST', body: Object.fromEntries(new FormData(e.target)) }); toastFixed('节点已登记，请继续配置模型并检查连接。'); await adminNodes(); } catch (error) { $('#node-error').textContent = error.message; handleError(error); } };
  document.querySelectorAll('.drain-node').forEach(b => { b.onclick = () => client.request('/admin/nodes/' + b.dataset.id, { method: 'PUT', body: { draining: b.dataset.draining !== '1' } }).then(adminNodes).catch(handleError); });
}
async function adminBudgets() {
  const info = await client.request('/admin/budgets'), reconciliation = await client.request('/admin/reconciliation');
  $('#admin-content').innerHTML = `<div class="admin-lower"><section class="panel"><div class="panel-title"><h2>在线 API 预算</h2><span class="status">北京时间结算</span></div><div class="info-note">未配置预算的币种无法启用在线模型。每次任务先预占费用上限，完成后结算；不同币种独立累计。</div><form id="budget-form"><div class="form-columns"><label>币种<select name="currency"><option>CNY</option><option>USD</option></select></label><label>每日预算<input name="daily" type="number" min="0" step="0.01" required></label></div><label>每月预算<input name="monthly" type="number" min="0" step="0.01" required></label><p id="budget-error" class="error"></p><button class="primary">保存预算</button></form></section><section class="panel"><h2>预算使用记录</h2><div class="table-wrap"><table><thead><tr><th>周期</th><th>币种</th><th>已记账</th><th>预占</th></tr></thead><tbody>${info.usage.map(r => `<tr><td>${esc(r.period)}</td><td>${r.currency}</td><td>${(r.used / 1e6).toFixed(4)}</td><td>${(r.reserved / 1e6).toFixed(4)}</td></tr>`).join('')}</tbody></table></div>${!info.usage.length ? '<p class="muted">暂无在线 API 使用记录。</p>' : ''}</section></div><section class="panel reconcile-panel"><h2>待核对费用</h2><p class="muted small">未知结果在24小时后退回音乐使用额度，并按费用上限暂记。根据供应商账单完成核对。</p>${reconciliation.map(r => `<div class="reconcile-row"><code>${r.task_id.slice(0, 12)}</code><span><span ${stateLabel(r.state) !== r.state ? 'data-strgo-ui-copy' : 'data-strgo-user-content'}>${stateLabel(r.state)}</span> · ${r.currency} ${((r.cost ?? r.max_cost) / 1e6).toFixed(4)}</span>${r.provisional ? `<button class="text-button reconcile-cost" data-id="${r.task_id}" data-cost="${r.cost}" data-currency="${r.currency}">录入实际费用 ↗</button>` : '<span class="muted">等待上游核对</span>'}</div>`).join('') || '<p class="muted">目前没有待核对记录。</p>'}</section>`;
  const update = () => { const v = info.budgets.find(b => b.currency === $('#budget-form').elements.currency.value); $('#budget-form').elements.daily.value = v ? v.daily / 1e6 : ''; $('#budget-form').elements.monthly.value = v ? v.monthly / 1e6 : ''; }; $('#budget-form').elements.currency.onchange = update; update();
  $('#budget-form').onsubmit = async e => { e.preventDefault(); const f = e.target; try { await client.request('/admin/budgets', { method: 'PUT', body: { currency: f.elements.currency.value, daily: Math.round(Number(f.elements.daily.value) * 1e6), monthly: Math.round(Number(f.elements.monthly.value) * 1e6) } }); toastFixed('预算已更新。'); await adminBudgets(); } catch (error) { $('#budget-error').textContent = error.message; handleError(error); } };
  document.querySelectorAll('.reconcile-cost').forEach(b => { b.onclick = () => { modal(`<h2>核对实际费用</h2><form id="reconcile-form"><label><span data-strgo-ui-copy>实际费用（${esc(b.dataset.currency)}）</span><input name="cost" type="number" min="0" step="0.000001" value="${Number(b.dataset.cost) / 1e6}" required></label><label>供应商账单 / 工单编号<input name="reference" maxlength="100" required></label><p id="reconcile-error" class="error"></p><button class="primary full">确认核对</button></form>`); $('#reconcile-form').onsubmit = async e => { e.preventDefault(); try { await client.request('/admin/reconciliation/' + b.dataset.id, { method: 'PUT', body: { cost_micro: Math.round(Number(e.target.elements.cost.value) * 1e6), reference: e.target.elements.reference.value } }); $('#dialog').close(); toastFixed('费用已核对，额度不会重复结算。'); await adminBudgets(); } catch (error) { $('#reconcile-error').textContent = error.message; handleError(error); } }; }; });
}
async function adminRequests() {
  const requests = await client.request('/admin/requests'), models = await client.request('/admin/models');
  $('#admin-content').innerHTML = `<section class="panel"><div class="panel-title"><h2>权限申请</h2></div>${requests.map(r => `<article class="request-row"><div><h3><span data-strgo-user-content>${esc(r.username)}</span> <span class="status" data-strgo-ui-copy>${{ pending: '待审核', approved: '已通过', rejected: '已拒绝' }[r.state]}</span></h3><p data-strgo-ui-copy>${JSON.parse(r.modules).map(k => k === 'music' ? '音乐生成' : 'AI 对话').join(' / ')}</p><p class="muted" ${r.reason ? 'data-strgo-user-content' : 'data-strgo-ui-copy'}>${esc(r.reason || '未填写说明')}</p></div>${r.state === 'pending' ? `<div class="button-row"><button class="primary review-request" data-id="${r.id}">审核授权</button><button class="secondary reject-request" data-id="${r.id}">拒绝</button></div>` : ''}</article>`).join('') || empty('暂时没有权限申请', '新成员提交申请后会出现在这里。', 'tasks')}</section>`;
  document.querySelectorAll('.reject-request').forEach(b => { b.onclick = () => client.request('/admin/requests/' + b.dataset.id, { method: 'PUT', body: { state: 'rejected' } }).then(adminRequests).catch(handleError); });
  document.querySelectorAll('.review-request').forEach(b => { b.onclick = () => { const request = requests.find(r => r.id === b.dataset.id), modules = JSON.parse(request.modules); modal(`<h2><span>授权给</span> <span data-strgo-user-content>${esc(request.username)}</span></h2><p class="muted"><span>模块：</span>${modules.map(k => `<span>${k === 'chat' ? '对话' : '音乐'}</span>`).join(' / ')}。 <span>授权有效期为 30 天，默认每日 50 次对话和 600 秒音乐。</span></p><form id="review-form"><h3>选择可用模型</h3>${models.filter(m => modules.includes(m.kind)).map(m => `<label class="checkbox"><input type="checkbox" name="models" value="${m.id}"><span data-strgo-user-content>${esc(modelLabel(m))}</span></label>`).join('')}<p class="error" id="review-error"></p><button class="primary full">通过并授权</button></form>`); $('#review-form').onsubmit = async e => { e.preventDefault(); try { const selected = [...e.target.querySelectorAll('input:checked')].map(v => v.value); if (!modules.every(k => selected.some(id => models.find(m => m.id === id)?.kind === k))) throw new Error('请为每个申请的模块至少选择一个模型。'); await client.request('/admin/requests/' + request.id, { method: 'PUT', body: { state: 'approved', models: selected } }); $('#dialog').close(); toastFixed('申请已通过。'); await adminRequests(); } catch (error) { $('#review-error').textContent = error.message; handleError(error); } }; }; });
}
async function adminAudit() {
  const entries = await client.request('/admin/audit');
  $('#admin-content').innerHTML = `<section class="panel table-panel"><div class="panel-title"><h2>审计日志</h2><p class="small muted">记录权限、配置与结算操作；不包含用户对话、歌词或密钥。</p></div><div class="table-wrap"><table><thead><tr><th>时间</th><th>操作</th><th>资源</th><th>元数据</th></tr></thead><tbody>${entries.map(r => `<tr><td>${new Date(r.created * 1000).toLocaleString('zh-CN')}</td><td>${esc(r.action)}</td><td><code>${esc(r.resource.slice(0, 14) || '—')}</code></td><td><code>${esc(r.detail)}</code></td></tr>`).join('')}</tbody></table></div></section>`;
}

async function start() {
  try { state.session = await client.refreshSession(); if (state.session.user) state.models = await client.request('/models'); }
  catch (error) { state.offline = true; state.session = client.session = { user: null, csrf: '' }; }
  shell();
  if (state.offline) $('.workspace').insertAdjacentHTML('afterbegin', '<div class="service-banner">账号与 AI 服务暂未连接。管理员可按 AI-WORKSPACE.md 完成配置。</div>');
  if (state.session?.demo) $('.workspace').insertAdjacentHTML('afterbegin', '<div class="service-banner">界面验收演示 · 临时数据与静音测试音频 · 未调用真实模型</div>');
  try { await ({ music: musicPage, chat: chatPage, overview: overviewPage, tasks: tasksPage, assets: assetsPage, settings: settingsPage, admin: adminPage, login: settingsPage }[route] || overviewPage)(); if (route === 'login') authDialog(); }
  catch (error) { if (!$('#main').children.length) $('#main').innerHTML = `<section class="panel error-panel">${empty('暂时无法打开工作区', esc(error.message), 'help', false)}<a href="${esc(location.pathname)}" class="secondary">重新加载</a></section>`; handleError(error); }
}
window.addEventListener('pagehide', () => clearInterval(state.polling));
start();

window.addEventListener('beforeunload', event => { if (state.formDirty) { event.preventDefault(); event.returnValue = ''; } });
